import * as D from './domain.mjs';import {LocalRepository,empty} from './store.mjs';import * as E from './editing.mjs';import {bindEnterNavigation} from './keyboard.mjs';
const repo=new LocalRepository();let s;try{s=repo.load()}catch(e){document.querySelector('#notice').textContent=e.message;throw e}let page='Visão geral',draft=null,xmlDraft=null,editingMaterial=null,editingSupplier=null,revisingPurchase=null,editingQuote=null;const formDrafts=new Map();const $=x=>document.querySelector(x),id=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('en-CA'),br=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=x=>x?x.slice(0,10).split('-').reverse().join('/'):'—',sum=a=>a.reduce((v,x)=>v+x,0),field=(n,t,type='text',value='',extra='')=>'<label>'+t+'<input name="'+n+'" type="'+type+'" value="'+esc(value)+'" '+extra+' required></label>',select=(n,t,opts)=>'<label>'+t+'<select name="'+n+'">'+opts+'</select></label>',options=(a,key='description')=>a.map(m=>'<option value="'+m.id+'">'+esc(m[key])+'</option>').join(''),table=(heads,rows)=>'<table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+ (rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="20" class="muted">Nenhum registro neste período.</td></tr>')+'</tbody></table>',section=(title,body)=>'<section><h2>'+title+'</h2>'+body+'</section>',btn=(text,action,cls='')=>'<button type="button" class="'+cls+'" data-action="'+action+'">'+text+'</button>';
function save(){repo.save(s)}function download(name,text,type){let u=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
let pages=['Visão geral','Materiais e fornecedores','Importar XML','Lançamento manual','Compras registradas','Aprovação de custos','Equipe e produção','Custos e preços','Contas a pagar','Relatórios','Configurações'];
function render(){captureFormDrafts(); $('#title').textContent=page;$('#nav').innerHTML=pages.map((p,i)=>'<button data-page="'+i+'" class="'+(p===page?'active':'')+'">'+String(i+1).padStart(2,'0')+' &nbsp; '+p+'</button>').join('');$('#view').innerHTML='<div class="session-warning" role="note">Dados salvos neste navegador. Enter avança entre campos; use os botões para salvar. Exporte backups regularmente.</div>'+views[page]();bind();restoreFormDrafts()}
const views={
'Visão geral':()=>{let ps=s.purchases.flatMap(p=>p.installments),balance=p=>D.money(p.amount-sum(p.payments.map(x=>x.amount))),over=ps.filter(p=>p.due<today()&&balance(p)>0);return '<p class="muted">Custos sob controle. Decisões com rastreabilidade.</p><div class="cards">'+[['Compras registradas',br(sum(s.purchases.map(p=>p.total))),'Valor das compras'],['Aprovações pendentes',s.proposals.filter(p=>p.status==='pending').length,'Aguardando revisão manual'],['Contas em aberto',br(sum(ps.map(balance))),'Saldo total pendente'],['Valores em atraso',br(sum(over.map(balance))),'Pelo vencimento das parcelas']].map(x=>'<div class="card">'+x[0]+'<strong>'+x[1]+'</strong><em>'+x[2]+'</em></div>').join('')+section('Próximos compromissos',table(['Vencimento','Fornecedor','Saldo','Situação'],s.purchases.flatMap(p=>p.installments.filter(x=>balance(x)>0).map(x=>[date(x.due),esc(p.supplier),br(balance(x)),'<span class="tag">'+D.installmentStatus(x,today())+'</span>'])).sort((a,b)=>a[0].localeCompare(b[0])).slice(0,8)))+section('Referências dos últimos três meses completos',materialReferences())},
'Materiais e fornecedores':()=>materialsView(),
'Importar XML':()=>invoiceImportView(),
'Lançamento manual':()=>section('Entrada manual','<form id="purchase" data-flow="manual">'+select('materialId','Material',options(s.materials))+field('supplier','Fornecedor')+'<label>Documento / referência (opcional)<input name="number"></label>'+select('documentStatus','Situação documental','<option>Sem nota fiscal</option><option>Documentação parcial</option><option>Conferida</option>')+field('issued','Emissão','date',today())+field('received','Recebimento','date',today())+field('quantity','Quantidade de compra','number',1,'min="0.000001" step="any"')+field('factor','Unidades de consumo / compra','number',1,'min="0.000001" step="any"')+field('total','Valor dos produtos','number',0,'min="0" step="any"')+field('discount','Desconto','number',0,'min="0" step="any"')+field('freight','Frete atribuído','number',0,'min="0" step="any"')+field('other','Outras despesas atribuídas','number',0,'min="0" step="any"')+field('count','Parcelas','number',1,'min="1" max="120"')+field('due','Primeiro vencimento','date',today())+'<button>Registrar entrada</button></form>'),
'Compras registradas':()=>section('Compras registradas',table(['Referência','Fornecedor','Emissão','Recebimento','Documentação','Valor'],s.purchases.map(p=>[esc(p.number||'Sem referência'),esc(p.supplier),date(p.issued),date(p.received),esc(p.documentStatus),br(p.total)])))+s.purchases.filter(p=>p.totals).map(p=>section('NF-e '+esc(p.number)+' — conferência',invoiceDetails(p)+btn('Editar itens da nota','edit-invoice:'+p.id))).join(''),
'Aprovação de custos':()=>invoiceApprovalView()+section('Custos avulsos e lançamentos manuais','<div class="row">'+field('actor','Responsável')+btn('Aprovar selecionados','approve')+btn('Rejeitar selecionados','reject','danger')+'</div>'+table(['Selecionar','Material','Anterior','Proposto','Diferença','Variação'],s.proposals.filter(p=>p.status==='pending'&&!s.purchases.some(n=>n.id===p.purchaseId&&n.approveWholeInvoice)).map(p=>['<input type="checkbox" class="proposal" value="'+p.id+'">',esc(s.materials.find(m=>m.id===p.materialId)?.description),p.old===null?'Sem custo':br(p.old),br(p.cost),p.old===null?'—':br(p.cost-p.old),p.old?((p.cost/p.old-1)*100).toFixed(2)+'%':'—'])))+section('Referência sugerida',materialReferences())+section('Auditoria',table(['Data','Responsável','Decisão','Anterior','Novo'],s.audit.map(a=>[new Date(a.at).toLocaleString('pt-BR'),esc(a.actor),a.action==='material-edited'?'Material editado':a.action==='supplier-edited'?'Fornecedor editado':a.action==='invoice-edited'?'Itens da nota editados':a.action==='invoice-approved'?'Nota '+esc(a.number)+' aprovada':a.action==='invoice-rejected'?'Nota '+esc(a.number)+' rejeitada':a.action==='approved'?'Custo aprovado':'Custo rejeitado',a.old==null?'—':br(a.old),a.total==null&&a.cost==null?'—':br(a.total??a.cost)]))),
'Equipe e produção':()=>section('Custo de mão de obra','<p>Informe provisões e encargos da RR. Encargos incidem sobre salário e provisões. Não inclua novamente esses valores nos rateios.</p><form id="employee">'+field('name','Funcionário / identificação')+field('salary','Salário mensal','number','','min="0" step="any"')+field('thirteenth','Provisão 13º (%)','number','','min="0" step="any"')+field('vacation','Provisão férias + adicional (%)','number','','min="0" step="any"')+field('charges','FGTS + outros encargos (%)','number','','min="0" step="any"')+field('hours','Horas produtivas mensais','number','','min="0.01" step="any"')+'<button>Cadastrar</button></form>'+table(['Funcionário','Custo/hora'],s.employees.map(e=>[esc(e.name),br(D.hourly(e))])))+section('Etapas produtivas','<p class="muted">Tempo por bloco iniciado de 100 mm, por elemento. Mesma referência para todos os diâmetros.</p><form id="step">'+field('name','Etapa')+select('employeeId','Funcionário',options(s.employees,'name'))+field('minutes','Minutos / 100 mm','number','','min="0" step="any"')+'<button>Cadastrar etapa</button></form>'+table(['Etapa','Minutos / 100 mm'],s.steps.map(t=>[esc(t.name),t.minutes]))),
'Custos e preços':()=>section('Orçamento de resistência tubular','<p class="muted">Dimensões finais após compactação. Informe os consumos técnicos; nenhuma geometria é presumida.</p><form id="quote">'+field('name','Identificação')+field('diameter','Diâmetro (mm)','number','','min="0.01" step="any"')+field('length','Comprimento final (mm)','number','','min="0.01" step="any"')+field('elements','Elementos','number',1,'min="1"')+field('factory','Indiretos de fabricação atribuídos (R$)','number','','min="0" step="any"')+field('admin','Administrativo atribuído (R$)','number','','min="0" step="any"')+field('tax','Tributos sobre venda (%)','number','','min="0" step="any"')+field('margin','Margem líquida desejada (%)','number','','min="0" step="any"')+select('mode','Método','<option value="margin">Margem líquida alvo</option><option value="markup">Multiplicador (markup)</option>')+field('markup','Multiplicador','number',1,'min="0.01" step="any"')+field('discount','Desconto (%)','number',0,'min="0" max="100" step="any"')+'<div style="grid-column:1/-1">'+table(['Usar','Material / acessório','Consumo','Base'],s.materials.map(m=>['<input type="checkbox" name="use'+m.id+'">',esc(m.description)+' ('+esc(m.unit)+')','<input type="number" name="qty'+m.id+'" min="0" step="any" value="'+(/nippl/i.test(m.description)?2:1)+'">','<select name="basis'+m.id+'"><option value="set">Conjunto completo</option><option value="element" '+(/nippl|termin/i.test(m.description)?'selected':'')+'>Por elemento</option><option value="length">Por metro de elemento</option></select>']))+'<p>Cabeçote e flange: use conjunto completo. Terminais: informe a quantidade por elemento. Nipples: sugestão de 2 por elemento, ajustável.</p></div><button>Calcular e salvar versão</button></form>')+(draft?quoteResult(draft):'')+section('Orçamentos salvos',table(['Data','Identificação','Custo','Venda','Resultado líquido','Ação'],s.quotes.map(q=>[date(q.at),esc(q.name),br(q.result.cost),br(q.result.sale),br(q.result.net),btn('Editar produto / criar revisão','edit-quote:'+q.id)]))),
'Contas a pagar':()=>section('Parcelas e pagamentos',table(['Compra','Vencimento','Valor','Pago','Saldo','Situação','Ação'],s.purchases.flatMap(p=>p.installments.map(x=>{let paid=sum(x.payments.map(y=>y.amount));return [esc(p.number)+' • '+esc(p.supplier),date(x.due),br(x.amount),br(paid),br(D.money(x.amount-paid)),'<span class="tag">'+D.installmentStatus(x,today())+'</span>',paid<x.amount?btn('Registrar pagamento','pay:'+x.id):'Quitada']}))))+section('Histórico de quitações',table(['Referência','Data','Valor'],s.purchases.flatMap(p=>p.installments.flatMap(x=>x.payments.map(y=>[esc(p.number),date(y.date),br(y.amount)]))))) ,
'Relatórios':()=>section('Período de referência','<p>O padrão cobre os últimos três meses completos. Recebimentos usam a data de entrada; financeiro usa vencimentos e pagamentos.</p><form id="period">'+field('start','Início','date',period.start)+field('end','Fim exclusivo','date',period.end)+'<button>Consultar</button></form><div class="row" style="margin-top:20px">'+btn('Exportar Excel (.xls)','excel')+btn('Exportar PDF / imprimir','pdf')+'</div>')+'<div id="report">'+report()+'</div>',
'Configurações':()=>section('Dados e portabilidade','<p>Dados persistentes neste navegador. Recarregar não apaga a base. Exporte backups regularmente. Restaurar backup substitui os dados após confirmação.</p><label>Restaurar backup JSON<input type="file" id="restore" accept=".json"></label><p>'+btn('Carregar exemplo demonstrativo','demo')+'</p><p>Integração futura: contrato technical-input.schema.json. A calculadora existente não é acessada nem modificada.</p>')};
let period=D.window3(today());
function materialReferences(){return table(['Material','Aprovado','Maior custo efetivo','Referência'],s.materials.map(m=>{let r=D.referenceCost(s.entries,m.id,today());return [esc(m.description),m.cost===null?'—':br(m.cost),r===null?'—':br(r),r===null?'<span class="tag">Desatualizada</span>':'Últimos 3 meses completos']}))}
function quoteResult(q){return section('Composição do preço',table(['Componente','Valor'],[['Materiais',br(q.materials)],['Acessórios',br(q.accessories)],['Mão de obra',br(q.labor)],['Indiretos de fabricação',br(q.factory)],['Administrativo',br(q.admin)],['Custo total',br(q.cost)],['Preço antes do desconto',br(q.price)],['Preço com desconto',br(q.sale)],['Resultado líquido estimado',br(q.net)],['Markup',q.markup.toFixed(3)+'×'],['Margem bruta',(q.gross*100).toFixed(2)+'%'],['Margem líquida estimada',(q.netMargin*100).toFixed(2)+'%']])+table(['Material','Consumo','Custo'],q.lines.map(l=>[esc(l.name),l.quantity,br(l.total)])))}
function report(){let entries=s.entries.filter(e=>e.received>=period.start&&e.received<period.end),by={};entries.forEach(e=>{by[e.supplier]=(by[e.supplier]||0)+e.cost*e.quantity*e.factor});let start=new Date(period.start+'T12:00:00Z'),end=new Date(period.end+'T12:00:00Z'),days=(end-start)/86400000,prev=new Date(+start-days*86400000).toISOString().slice(0,10),old=s.entries.filter(e=>e.received>=prev&&e.received<period.start),total=sum(entries.map(e=>e.cost*e.quantity*e.factor)),oldtotal=sum(old.map(e=>e.cost*e.quantity*e.factor));return section('Entradas por recebimento', '<p>Total: <b>'+br(total)+'</b> • Período anterior de igual duração: '+br(oldtotal)+' • Variação: '+(oldtotal?((total/oldtotal-1)*100).toFixed(2)+'%':'sem base')+'</p>'+table(['Entrada','Material','Quantidade consumo','Unidade','Custo unitário','Total'],entries.map(e=>[date(e.received),esc(s.materials.find(m=>m.id===e.materialId)?.description),e.quantity*e.factor,esc(s.materials.find(m=>m.id===e.materialId)?.unit),br(e.cost),br(e.cost*e.quantity*e.factor)])))+section('Compras por fornecedor',table(['Fornecedor','Total recebido'],Object.entries(by).map(([k,v])=>[esc(k),br(v)])))+section('Evolução dos custos aprovados',table(['Material','Anterior','Novo','Variação'],s.audit.filter(a=>a.action==='approved'&&a.at.slice(0,10)>=period.start&&a.at.slice(0,10)<period.end).sort((a,b)=>(b.old?b.cost/b.old:0)-(a.old?a.cost/a.old:0)).map(a=>[esc(s.materials.find(m=>m.id===a.materialId)?.description),a.old===null?'—':br(a.old),br(a.cost),a.old?((a.cost/a.old-1)*100).toFixed(2)+'%':'—'])))+section('Financeiro por vencimento',table(['Fornecedor','Vencimento','Valor','Saldo'],s.purchases.flatMap(p=>p.installments.filter(x=>x.due>=period.start&&x.due<period.end).map(x=>[esc(p.supplier),date(x.due),br(x.amount),br(x.amount-sum(x.payments.map(y=>y.amount)))]))))+section('Pagamentos no período',table(['Fornecedor','Data','Pago'],s.purchases.flatMap(p=>p.installments.flatMap(x=>x.payments.filter(y=>y.date>=period.start&&y.date<period.end).map(y=>[esc(p.supplier),date(y.date),br(y.amount)])))))+section('Composição dos orçamentos',table(['Identificação','Custo','Venda','Resultado'],s.quotes.filter(q=>q.at>=period.start&&q.at<period.end).map(q=>[esc(q.name),br(q.result.cost),br(q.result.sale),br(q.result.net)])))}
function onForm(name,fn){let f=$('#'+name);if(f)f.onsubmit=e=>{e.preventDefault();let before=structuredClone(s);try{fn(Object.fromEntries(new FormData(e.currentTarget)),f);save();f.dataset.skipDraft='true';render();$('#notice').textContent='Operação concluída.'}catch(e){s=before;$('#notice').textContent=e.message}}}
function bind(){if(editingQuote&&page==='Custos e preços'){let quote=s.quotes.find(q=>q.id===editingQuote);if(quote){for(let [name,value] of Object.entries(quote.input)){if(name==='lines')continue;let input=$('#quote [name="'+name+'"]');if(input)input.value=value}for(let line of quote.input.lines){let use=$('#quote [name="use'+line.materialId+'"]'),qty=$('#quote [name="qty'+line.materialId+'"]'),basis=$('#quote [name="basis'+line.materialId+'"]');if(use)use.checked=true;if(qty)qty.value=line.quantity;if(basis)basis.value=line.basis}}}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=pages[+b.dataset.page];$('#notice').textContent='';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));onForm('supplier',v=>{if(editingSupplier){E.editSupplier(s,editingSupplier,v,v.actor);editingSupplier=null}else s.suppliers.push({...v,id:id()})});onForm('material',v=>{if(editingMaterial){E.editMaterial(s,editingMaterial,v,v.actor);editingMaterial=null}else{if(!s.suppliers.some(f=>f.id===v.supplier))throw Error('Cadastre ou selecione o fornecedor');if(s.materials.some(m=>m.code===v.code&&m.supplier===v.supplier))throw Error('Código já cadastrado para o fornecedor');let m={...v,id:id(),purchaseFactor:D.positive(v.purchaseFactor,'Conversão',false),cost:null};s.materials.push(m);s.proposals.push({id:id(),materialId:m.id,cost:D.positive(v.cost),old:null,status:'pending',at:today(),unit:m.unit})}});onForm('employee',v=>{D.hourly(v);s.employees.push({...v,id:id()})});onForm('step',v=>{if(!v.employeeId)throw Error('Cadastre um funcionário');s.steps.push({...v,id:id()})});onForm('purchase',v=>{let item={...v};['quantity','factor','total','discount','freight','other'].forEach(k=>item[k]=Number(item[k]));let total=item.total-item.discount+item.freight+item.other;if(total<0)throw Error('Desconto excede a compra');D.registerPurchase(s,{...v,id:id(),origin:'manual',items:[item],total,installments:D.split(total,+v.count,v.due)})});onForm('invoice-edit',v=>{xmlDraft=E.editInvoiceDraft(xmlDraft,xmlDraft.items.map((x,i)=>{let p={taxes:{}};for(let k of ['code','description','unit','quantity','unitPrice','total','discount','freight','insurance','other'])p[k]=v['item'+i+'_'+k];for(let k of Object.keys(x.taxes||{}))p.taxes[k]=v['item'+i+'_'+k];return p}))});onForm('import',v=>{let settings={received:v.received,due:v.due,items:xmlDraft.items.map((x,i)=>({selected:!!v['pick'+i],materialId:v['mat'+i]||null,category:v['category'+i],factor:+v['factor'+i],unit:v['unit'+i],confirmConversion:!!v['confirm'+i]}))};if(revisingPurchase){E.reviseInvoice(s,revisingPurchase,xmlDraft,settings,v.revisionActor);revisingPurchase=null}else D.importInvoice(s,xmlDraft,settings);xmlDraft=null;page='Compras registradas'});onForm('quote',(v)=>{let lines=s.materials.filter(m=>v['use'+m.id]).map(m=>({materialId:m.id,quantity:+v['qty'+m.id],basis:v['basis'+m.id]}));if(!lines.length)throw Error('Selecione os materiais');if(!s.steps.length)throw Error('Cadastre as etapas produtivas');let q={...v,lines};draft=D.quote(s,q);s.quotes.push({id:id(),name:v.name,at:today(),input:q,result:draft,revisedFrom:editingQuote});editingQuote=null});onForm('period',v=>{if(v.start>=v.end)throw Error('Período inválido');period=v});if($('#xml'))$('#xml').onchange=async e=>{try{revisingPurchase=null;xmlDraft=D.parseNfe(await e.target.files[0].text());if(s.purchases.some(p=>p.key===xmlDraft.key))throw Error('Nota já importada');render()}catch(e){xmlDraft=null;$('#notice').textContent=e.message}};if($('#restore'))$('#restore').onchange=async e=>{try{let data=repo.validate(JSON.parse(await e.target.files[0].text()));if(confirm('Substituir todos os dados locais pelo backup?')){s=data;save();render()}}catch(e){$('#notice').textContent=e.message}}}
function action(a){try{if(a.startsWith('edit-quote:')){editingQuote=a.slice(11);page='Custos e preços'}if(a.startsWith('edit-material:')){editingMaterial=a.slice(14);page='Materiais e fornecedores'}if(a==='cancel-material')editingMaterial=null;if(a.startsWith('edit-supplier:')){editingSupplier=a.slice(14);page='Materiais e fornecedores'}if(a==='cancel-supplier')editingSupplier=null;if(a.startsWith('edit-invoice:')){let p=s.purchases.find(p=>p.id===a.slice(13));if(!p)throw Error('Nota não encontrada');revisingPurchase=p.id;xmlDraft=p.workingInvoice?{...structuredClone(p.workingInvoice),rawXml:p.rawXml}:D.parseNfe(p.rawXml);page='Importar XML'}if(a==='cancel-invoice'){revisingPurchase=null;xmlDraft=null}if(a==='approve-invoices'||a==='reject-invoices'){let ids=[...document.querySelectorAll('.invoice:checked')].map(x=>x.value),actor=document.querySelector('[name=invoiceActor]').value;if(!ids.length)throw Error('Selecione ao menos uma nota');if(!actor.trim())throw Error('Informe o responsável');let notes=ids.map(id=>s.purchases.find(p=>p.id===id)),total=sum(notes.map(p=>p.total));if(confirm((a==='approve-invoices'?'Aprovar':'Rejeitar')+' integralmente '+notes.length+' nota(s), total '+br(total)+'? Todos os custos vinculados serão decididos em conjunto.')){let next=structuredClone(s);ids.forEach(id=>D.decideInvoice(next,id,a==='approve-invoices',actor));s=next}}if(a==='approve'||a==='reject'){let ids=[...document.querySelectorAll('.proposal:checked')].map(x=>x.value);if(!ids.length)throw Error('Selecione propostas');let selected=s.proposals.filter(p=>ids.includes(p.id));if(a==='approve'&&new Set(selected.map(p=>p.materialId)).size!==selected.length)throw Error('Aprove apenas uma proposta por material de cada vez');if(confirm('Confirmar decisão para '+ids.length+' custo(s)?'))D.decide(s,ids,a==='approve',document.querySelector('[name=actor]').value)}if(a.startsWith('pay:')){let p=s.purchases.flatMap(x=>x.installments).find(x=>x.id===a.slice(4)),amount=prompt('Valor pago (use ponto decimal):'),date=prompt('Data do pagamento (AAAA-MM-DD):',today());if(amount!==null&&date!==null){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isNaN(Date.parse(date)))throw Error('Data inválida');D.pay(p,+amount,date)}}if(a==='pdf')window.print();if(a==='excel')download('relatorio-elvira.xls','<html><meta charset="utf-8"><body>'+report()+'</body></html>','application/vnd.ms-excel');if(a==='demo'){if(s.materials.length||s.purchases.length)throw Error('Use uma base vazia para carregar a demonstração');let supplier=id(),m=id();s.suppliers.push({id:supplier,name:'DEMONSTRAÇÃO • Fornecedor exemplo',document:'Fictício'});s.materials.push({id:m,code:'DEMO-001',description:'DEMONSTRAÇÃO • Tubo por metro',category:'Matéria-prima',buyUnit:'barra',unit:'m',supplier,cost:null});s.proposals.push({id:id(),materialId:m,old:null,cost:25,status:'pending',at:today()})}save();render()}catch(e){$('#notice').textContent=e.message}}
bindEnterNavigation(document);
$('#backup').onclick=()=>download('backup-elvira-'+today()+'.json',JSON.stringify(s,null,2),'application/json');render();

function findInvoiceMaterial(x){if(revisingPurchase){let p=s.purchases.find(p=>p.id===revisingPurchase),item=p?.items.find(item=>item.line===x.line);if(item?.materialId)return s.materials.find(m=>m.id===item.materialId)}let supplier=s.suppliers.find(f=>String(f.document||'').replace(/\D/g,'')===xmlDraft.supplierDocument.replace(/\D/g,''));return s.materials.find(m=>m.supplier===supplier?.id&&m.code===x.code)}
function categoryOptions(value){return '<option value="">Escolha a categoria</option>'+['Matéria-prima','Acessório','Componente'].map(c=>'<option '+(c===value?'selected':'')+'>'+c+'</option>').join('')}
function invoiceDetails(n){let t=n.totals;return '<p><b>'+esc(n.supplier)+'</b> • CNPJ/CPF: '+esc(n.supplierDocument)+' • NF '+esc(n.number)+' / série '+esc(n.series)+' • Emissão '+date(n.issued)+'</p><p style="overflow-wrap:anywhere">Chave: '+esc(n.key)+'</p>'+table(['Produtos','Desconto','Frete','Seguro','Outras despesas','IPI','II','ICMS-ST','FCP-ST','IPI devolvido','Desoneração ICMS','Total da NF-e'],[[br(t.vProd),br(t.vDesc),br(t.vFrete),br(t.vSeg),br(t.vOutro),br(t.vIPI),br(t.vII),br(t.vST),br(t.vFCPST),br(t.vIPIDevol),br(t.vICMSDeson),'<b>'+br(n.total)+'</b>']])+'<p>ICMS: '+br(t.vICMS)+' • PIS: '+br(t.vPIS)+' • COFINS: '+br(t.vCOFINS)+' • Tributos aproximados: '+br(t.vTotTrib)+'. Valores exibidos para conferência; não são somados novamente ao preço dos produtos.</p><p>Composição calculada: <b>'+br(n.calculatedTotal)+'</b> • Diferença: <b>'+br(n.difference)+'</b> • '+(n.reconciled?'<span class="tag good">Total conferido</span>':'<span class="tag">Registro bloqueado: total divergente</span>')+'</p>'+(n.warnings||[]).map(w=>'<p class="tag">'+esc(w)+'</p>').join('')+'<details><summary>Itens e valores originais da nota</summary>'+table(['Código','Descrição','Quantidade','Unidade','Preço unitário XML','Produtos','Desconto original','Frete original','Frete rateado','Impostos adicionais','Custo unitário com despesas'],(n.sourceItems||n.items).map(x=>[esc(x.code),esc(x.description),x.quantity,esc(x.unit),new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:10}).format(x.unitPrice),br(x.total),br(x.original?.discount??x.discount),br(x.original?.freight??x.freight),br(x.allocatedFreight),br((x.ipi||0)+(x.importDuty||0)+(x.st||0)+(x.fcpst||0)+(x.returnedIpi||0)),br(x.costUnit)]))+'</details>'+(n.installments?.length?'<h3>Vencimentos do XML</h3>'+table(['Duplicata','Vencimento','Valor'],n.installments.map(x=>[esc(x.number),date(x.due),br(x.amount)])):'<p class="tag">O XML não informa vencimento. Informe a data confirmada abaixo.</p>')}
function invoiceImportView(){return section('Importar NF-e XML','<input id="xml" type="file" accept=".xml"><p class="muted">Fornecedor, código, descrição e preço unitário são lidos da nota. O cadastro é automático ao confirmar a importação. Classifique os itens e confira as unidades.</p>'+(xmlDraft?invoiceDetails(xmlDraft)+invoiceFieldsEditor(xmlDraft)+'<form id="import" data-flow="xml">'+field('received','Recebimento','date',revisingPurchase?s.purchases.find(p=>p.id===revisingPurchase).received:today())+(revisingPurchase?field('revisionActor','Responsável pela edição'):'')+(!xmlDraft.installments.length?field('due','Vencimento confirmado (ausente no XML)','date',''):'')+'<div style="grid-column:1/-1">'+table(['Cadastrar / atualizar custo','Código e descrição do XML','Categoria','Vínculo de material','Unidade de consumo','Conversão consumo / compra','Confirmar mudança de unidade'],xmlDraft.items.map((x,i)=>{let m=findInvoiceMaterial(x);return ['<input type="checkbox" name="pick'+i+'" checked>',esc(x.code)+' • '+esc(x.description),'<select name="category'+i+'">'+categoryOptions(m?.category)+'</select>','<select name="mat'+i+'"><option value="">Automático: mesmo fornecedor + código</option>'+s.materials.map(t=>'<option value="'+t.id+'" '+(t.id===m?.id?'selected':'')+'>'+esc(t.code)+' • '+esc(t.description)+'</option>').join('')+'</select>','<input name="unit'+i+'" value="'+esc(m?.unit||x.unit)+'">','<input name="factor'+i+'" type="number" min="0.000001" step="any" value="'+esc(m?.purchaseFactor??(m&&m.unit!==x.unit?'':1))+'">','<input type="checkbox" name="confirm'+i+'">']}))+'<p>O frete destacado é distribuído proporcionalmente ao valor líquido dos produtos quando não estiver distribuído nos itens, com fechamento dos centavos. Desmarcar um item exclui somente seu cadastro de material: a compra e as parcelas permanecem pelo total integral da nota.</p></div><button '+(!xmlDraft.reconciled?'disabled':'')+'>'+(revisingPurchase?'Salvar edição da nota — ':'Importar nota completa — ')+br(xmlDraft.total)+'</button>'+(revisingPurchase?btn('Cancelar edição','cancel-invoice','secondary'):'')+'</form>':''))}
function invoiceApprovalView(){let pending=s.purchases.filter(p=>p.approveWholeInvoice&&p.approval==='pending');return section('Aprovar o valor total da nota','<p>Uma decisão abrange a nota inteira e todos os seus custos pendentes. O valor financeiro e os vencimentos seguem o XML.</p><div class="row">'+field('invoiceActor','Responsável pela nota')+btn('Aprovar notas selecionadas','approve-invoices')+btn('Rejeitar notas selecionadas','reject-invoices','danger')+'</div>'+table(['Selecionar','Nota','Fornecedor','Total integral','Custos vinculados','Vencimentos'],pending.map(p=>['<input type="checkbox" class="invoice" value="'+p.id+'">',esc(p.number),esc(p.supplier),'<b>'+br(p.total)+'</b>',s.proposals.filter(x=>x.purchaseId===p.id&&x.status==='pending').length,p.installments.map(x=>date(x.due)+' • '+br(x.amount)).join('<br>')]))) }

function materialsView(){let m=s.materials.find(x=>x.id===editingMaterial),f=s.suppliers.find(x=>x.id===editingSupplier);return section(m?'Editar material / produto':'Cadastrar material ou acessório','<p class="editing-note">Código, descrição, categoria, fornecedor, unidades e conversão são editáveis. O custo informado gera uma proposta para aprovação. Enter apenas avança entre os campos.</p><form id="material">'+field('code','Código','text',m?.code||'')+field('description','Descrição','text',m?.description||'')+select('category','Categoria',categoryOptions(m?.category||'Matéria-prima'))+select('supplier','Fornecedor',s.suppliers.map(x=>'<option value="'+x.id+'" '+(x.id===m?.supplier?'selected':'')+'>'+esc(x.name)+'</option>').join(''))+field('buyUnit','Unidade de compra','text',m?.buyUnit||'')+field('unit','Unidade de consumo','text',m?.unit||'')+field('purchaseFactor','Consumo por unidade de compra','number',m?.purchaseFactor??1,'min="0.000001" step="any"')+(m?'<label>Novo custo proposto (opcional)<input name="cost" type="number" min="0" step="any"></label>'+field('actor','Responsável pela edição')+'<p>Custo atualmente aprovado: '+(m.cost==null?'Pendente':br(m.cost))+'</p>':field('cost','Custo proposto (R$)','number','','min="0" step="any"'))+'<button type="submit">'+(m?'Salvar material':'Cadastrar')+'</button>'+(m?'<button type="button" data-action="cancel-material" class="secondary">Cancelar edição</button>':'')+'</form>')+section('Materiais e produtos',table(['Código','Descrição','Categoria','Compra / consumo','Conversão','Fornecedor','Custo aprovado','Ação'],s.materials.map(x=>[esc(x.code),esc(x.description),esc(x.category),esc(x.buyUnit)+' / '+esc(x.unit),x.purchaseFactor??1,esc(s.suppliers.find(f=>f.id===x.supplier)?.name||'—'),x.cost==null?'Pendente':br(x.cost),btn('Editar material','edit-material:'+x.id)])))+section(f?'Editar fornecedor':'Fornecedores','<form id="supplier">'+field('name','Razão social / nome','text',f?.name||'')+field('document','CNPJ / identificação','text',f?.document||'')+(f?field('actor','Responsável pela edição'):'')+'<button type="submit">'+(f?'Salvar fornecedor':'Cadastrar fornecedor')+'</button>'+(f?'<button type="button" data-action="cancel-supplier" class="secondary">Cancelar edição</button>':'')+'</form>'+table(['Nome','Documento','Ação'],s.suppliers.map(x=>[esc(x.name),esc(x.document),btn('Editar fornecedor','edit-supplier:'+x.id)])))}
function invoiceFieldsEditor(n){return '<details class="edit-panel"><summary>Editar campos dos produtos desta nota</summary><p>Edite os dados de trabalho dos itens. Os valores originais do XML permanecem preservados. Quantidade × preço deve conferir com o total de cada item; os itens precisam continuar fechando com os totais originais da nota. Salve a conferência antes de importar.</p><form id="invoice-edit">'+n.items.map((x,i)=>'<fieldset style="grid-column:1/-1"><legend>Item '+esc(x.line)+' — '+esc(x.code)+'</legend><div class="grid">'+[['code','Código'],['description','Descrição'],['unit','Unidade de compra']].map(([k,l])=>field('item'+i+'_'+k,l,'text',x[k])).join('')+[['quantity','Quantidade'],['unitPrice','Preço unitário'],['total','Total dos produtos'],['discount','Desconto'],['freight','Frete'],['insurance','Seguro'],['other','Outras despesas']].map(([k,l])=>field('item'+i+'_'+k,l,'number',x[k],(k==='quantity'?'min="0.000001"':'min="0"')+' step="any"')).join('')+Object.entries(x.taxes||{}).map(([k,v])=>field('item'+i+'_'+k,taxName(k)+' (R$)','number',v,'min="0" step="any"')).join('')+'</div></fieldset>').join('')+'<button type="submit">Salvar campos e conferir totais</button></form></details>'}

function formDraftKey(form){return form.id+'|'+(form.id==='material'?(editingMaterial||'new'):form.id==='supplier'?(editingSupplier||'new'):form.id==='quote'?(editingQuote||'new'):['import','invoice-edit'].includes(form.id)?(xmlDraft?.key||'new')+(revisingPurchase||''):page)}
function captureFormDrafts(){for(let form of document.querySelectorAll('#view form')){let key=form.dataset.draftKey;if(!key)continue;if(form.dataset.skipDraft==='true'){formDrafts.delete(key);continue}let fields={};for(let input of Array.from(form.elements)){if(!input.name||['file','submit','button','reset'].includes(input.type))continue;fields[input.name]={value:input.value,checked:input.checked}}formDrafts.set(key,fields)}}
function restoreFormDrafts(){for(let form of document.querySelectorAll('#view form')){let key=formDraftKey(form);form.dataset.draftKey=key;let fields=formDrafts.get(key);if(!fields)continue;for(let input of Array.from(form.elements)){let data=fields[input.name];if(!data||input.type==='file')continue;if(input.type==='checkbox'||input.type==='radio')input.checked=data.checked;else input.value=data.value}}}

function taxName(k){return ({vICMS:'ICMS',vICMSDeson:'ICMS desonerado',vFCP:'FCP',vICMSST:'ICMS-ST',vFCPST:'FCP-ST',vFCPSTRet:'FCP-ST retido',vICMSSTRet:'ICMS-ST retido',vIPI:'IPI',vII:'Imposto de importação (II)',vPIS:'PIS',vCOFINS:'COFINS',vIPIDevol:'IPI devolvido',vTotTrib:'Tributos aproximados',vISSQN:'ISSQN'})[k]||k}
